import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and current year `now`.

    The current year is supplied by the caller; the clock is never read.
    Returns now - born. Raises ValueError if now < born.
    """
    if now < born:
        raise ValueError("now is before born")
    return now - born


def test_typical_age() -> None:
    assert age_at(1990, 2024) == 34


def test_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_one_year_difference() -> None:
    assert age_at(1999, 2000) == 1


def test_century_span() -> None:
    assert age_at(1900, 2000) == 100


def test_across_year_zero_boundary() -> None:
    assert age_at(-10, 10) == 20


def test_returns_int() -> None:
    assert isinstance(age_at(1980, 2020), int)


def test_born_after_now_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_born_one_year_after_now_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)

